from argparse import Namespace

from .exception import CommandLineException


class SendBackupEnvironment:
    FISHEYE_URL = "https://fisheye3.inside.nsn.com/browse/robotlte/trunk/testsuite/"

    def __init__(self):
        self.no_config = True
        self.logging_level = None
        self.competence_area = None
        self.phase = None
        self.sw_version = None
        self.add_info = None
        self.robotlte_revision = None
        self.username = None
        self.rfsw_build = ""
        self.suite_path = ""
        self.ap_version = None
        self.tool = None
        self.ute_version = None
        self.cu_build = ""
        self.cu_caas_build = ""
        self.du_caas_build = ""
        self.fhgw_build = ""
        self.enb_nsa_build = ""
        self.gnb_nsa_build = ""
        self.customers = None
        self.rf_sw_line = ""
        self.rf_sw_branch = ""
        self.gnb_rf_shared_build = ""
        self.enb_rf_shared_build = ""
        self.bts2g_rf_shared_build = ""
        self.nb_rf_shared_build = ""
        self.qc_config_path = None
        self.custom_rp_url = None
        self.links = {}
        self.no_qc = None
        self.label = None
        self.fail_cause = None
        self.env_issue = None
        self.ignore_empty_suites = None
        self.executed_test_loops = None

    def _create_links_entries(self, cmd_args):  # noqa: C901
        result = {}
        if cmd_args.commits_link:
            result["Build commits"] = cmd_args.commits_link
        if cmd_args.log_link:
            result["Test logs"] = cmd_args.log_link
        elif cmd_args.build_link:
            result["Test logs"] = cmd_args.build_link
        if cmd_args.suite:
            result["Test file source code"] = "{}{}?hb=true".format(
                self._get_fisheye_url(cmd_args.fe),
                self._prepare_file_path(self.suite_path),
            )
        if cmd_args.execution_link:
            result["Execution link"] = cmd_args.execution_link
        if cmd_args.startup_analysis_diagram_link:
            result["Startup analysis diagram link"] = (
                cmd_args.startup_analysis_diagram_link
            )
        return result

    def _get_fisheye_url(self, fisheye_url=None):
        return self.FISHEYE_URL if fisheye_url is None else fisheye_url

    def _prepare_file_path(self, file_path):
        return (
            file_path.rsplit("testsuite", 1)[1]
            if file_path.startswith("testsuite")
            else file_path
        )

    def _resolve_label(self, cmd_args):
        return cmd_args.label if cmd_args.label else cmd_args.info

    def _is_dcm_build(self, cmd_args):
        if (
            "DCM" in str(self.label).upper()
            or "DNH" in str(cmd_args.sw_version).upper()
        ):
            return True
        return False

    @classmethod
    def from_cli_args(cls, cmd_args):
        instance = cls()
        instance.logging_level = cmd_args.debug
        instance.competence_area = cmd_args.ca
        instance.testline = cmd_args.tl
        instance.robotlte_revision = cmd_args.rr
        instance.username = cmd_args.username
        instance.no_qc = cmd_args.no_qc
        instance.phase = cmd_args.phase
        instance.add_info = cmd_args.info
        instance.product_type = cmd_args.product_type
        instance.load_prefix = cmd_args.load_prefix
        instance.tool = cmd_args.tool
        instance.no_config = cmd_args.no_config
        instance.ignore_empty_suites = cmd_args.ignore_empty_suites
        instance.sw_version = cmd_args.sw_version
        instance.ap_version = cmd_args.ap_version
        instance.customers = cmd_args.customers
        instance.rf_sw_line = cmd_args.rf_sw_line
        instance.rf_sw_branch = cmd_args.rf_sw_branch
        instance.custom_rp_url = cmd_args.rp
        instance.suite_path = cmd_args.suite
        instance.qc_config_path = cmd_args.qc_config_file
        instance.robot_output = cmd_args.robot_output
        try:
            instance.zipfile_path = cmd_args.zipfile_path
        except AttributeError:
            instance.zipfile_path = None
        instance.ute_version = cmd_args.ute_version
        instance.fail_cause = cmd_args.fail_cause
        instance.env_issue = cmd_args.env_issue
        instance.links = instance._create_links_entries(cmd_args)
        instance.label = instance._resolve_label(cmd_args)
        instance.dcm_build = instance._is_dcm_build(cmd_args)
        instance.cu_build = cmd_args.cu_build
        instance.cu_caas_build = cmd_args.cu_caas_build
        instance.du_caas_build = cmd_args.du_caas_build
        instance.fhgw_build = cmd_args.fhgw_build
        instance.enb_nsa_build = cmd_args.enb_nsa_build
        instance.gnb_nsa_build = cmd_args.gnb_nsa_build
        instance.gnb_rf_shared_build = cmd_args.gnb_rf_shared_build
        instance.enb_rf_shared_build = cmd_args.enb_rf_shared_build
        instance.bts2g_rf_shared_build = cmd_args.bts2g_rf_shared_build
        instance.nb_rf_shared_build = cmd_args.nb_rf_shared_build
        instance.rfsw_build = cmd_args.rfsw_build
        instance.executed_test_loops = cmd_args.executed_test_loops

        return instance

    @classmethod
    def from_dict(cls, inputs):
        instance = cls()

        instance.robot_output = inputs.get("robot_output")
        instance.username = inputs.get("username")
        instance.qc_config_path = inputs.get("qc_config_path")
        instance.sw_version = inputs.get("sw_version")
        instance.add_info = inputs.get("add_info")
        instance.ute_version = inputs.get("ute_version")
        instance.label = inputs.get("label")
        instance.suite_path = inputs.get("file_path")
        instance.testline = inputs.get("testline")
        instance.executed_test_loops = inputs.get("executed_test_loops")

        return instance


class SendFileEnvironment:

    def __init__(self):
        pass

    @classmethod
    def from_cli_args(cls, cmd_args):
        instance = cls()
        instance.logging_level = cmd_args.debug
        instance.zipfile_path = cmd_args.zipfile_path
        instance.custom_rp_url = cmd_args.rp
        instance.rfsw_build = cmd_args.rfsw_build
        return instance


class ValidateEnvironment:

    def __init__(self):
        pass

    @classmethod
    def from_cli_args(cls, cmd_args):
        instance = cls()
        instance.logging_level = cmd_args.debug
        instance.label = cmd_args.label
        instance.qc_config_path = cmd_args.qc_config_file
        instance.sw_version = cmd_args.sw_version
        instance.suite_path = cmd_args.suite
        instance.custom_rp_url = cmd_args.rp
        instance.rfsw_build = cmd_args.rfsw_build
        return instance


def environment_factory(command, input):
    """Factory function for managing environment (variables from cmd and newly created)

    :param  command:         Command that was ran by a user
    :param  input:           Command line arguments provided by a user

    :return:   A class that represents environment state
    :rtype:    SendBackupEnvironment | ValidateEnvironment

    """
    try:
        if isinstance(input, Namespace):
            return COMMANDS[command].from_cli_args(input)
        elif isinstance(input, dict):
            return COMMANDS[command].from_dict(input)
        else:
            raise ValueError(
                "Unsupported format of input for Environment creation, can be either dict or argparse.Namespace"
            )

    except KeyError:
        raise CommandLineException(f"Wrong command provided: {command}")


COMMANDS = {
    "send": SendBackupEnvironment,
    "backup": SendBackupEnvironment,
    "send_file": SendFileEnvironment,
    "validate": ValidateEnvironment,
}
